/**
 * Owner's "Guess Papers by Module" (2026-11-04): Part 1 (Q1–Q41) and Part 2
 * (M1.1–M9.9 so far, 69 questions; the rest of the PDF is still to come), each with its
 * explanation and memory trick, tagged to our lessons. Plus typed (fill the
 * blank / find the error) and drag-into-order questions for every milestone,
 * so a test cannot be cleared by clicking through MCQs.
 */
import { fillFor, orderFor, qsFor, type MKey, type WQuestion } from './types';

// Lesson titles (must match m1.ts … final.ts exactly).
const X = 'Xcode Installation & Simulator Setup', PG = 'Swift Playgrounds Basics', GIT = 'Git & GitHub Integration in Xcode';
const SW = 'What is Swift & Swift Features', CV = 'Constants, Variables & Type Inference', OP = 'Swift Operators';
const COL = 'Collections (Array, Set, Dictionary)', EN = 'Enumerations (Enums)', SC = 'Structures (Struct) vs Classes';
const AC = 'Access Control (private, public, open)', OPT = 'Swift Optionals & Unwrapping', ARC = 'ARC & Memory Management (Weak/Unowned)';
const FN = 'Functions & Argument Labels', CL = 'Closures & Trailing Closure Syntax', HOF = 'Higher-Order Functions (map, filter, reduce)';
const PR = 'Protocols & Protocol Extensions', GEN = 'Generics & Generic Constraints', EXT = 'Extensions & Protocol Conformance';
const ERR = 'Error Handling (throws, try, do-catch)', UI = 'UIKit (Imperative) vs SwiftUI (Declarative)';
const MVC = 'MVC Architecture', MVVM = 'MVVM Architecture', APP = 'App Life Cycle (AppDelegate / SceneDelegate / scenePhase)';
const VLC = 'View Life Cycle (viewDidLoad vs onAppear)', GCD = 'Grand Central Dispatch (GCD) & Queues', ASY = 'Async / Await Modern Concurrency';
const TASK = 'Tasks & Task Groups', ACT = 'Actors & @MainActor Thread Safety';
const NET = 'URLSession HTTP Networking', COD = 'JSON Parsing with Codable Protocol', VIEW = 'UIView & UIViewController Hierarchy';
const SB = 'Storyboards, IBOutlets & IBActions', AL = 'Auto Layout & Layout Constraints', TV = 'UI Controls & UITableView';
const SUI = 'What is SwiftUI & App Structure', LAY = 'SwiftUI Layouts (Stacks, Forms, Grids)', ST = 'State Management (@State, @Binding, @Observable)';
const NAV = 'NavigationStack & TabView', TGT = 'Xcode Project Targets & Build Settings', PL = 'Info.plist Permissions & Configuration';
const XCT = 'Unit Testing with XCTest & Mocks', INS = 'Xcode Instruments (Time Profiler, Leaks)';

const MS: Record<string, MKey> = {};
for (const l of [X, PG, GIT, SW, CV, OP, COL, EN, SC, AC, OPT, ARC, FN, CL, HOF, PR, GEN, EXT, ERR, UI]) MS[l] = 'm1';
for (const l of [MVC, MVVM, APP, VLC, GCD, ASY, TASK, ACT]) MS[l] = 'm2';
for (const l of [NET, COD, VIEW, SB, AL, TV]) MS[l] = 'm3';
for (const l of [SUI, LAY, ST, NAV, TGT, PL]) MS[l] = 'm4';
for (const l of [XCT, INS]) MS[l] = 'final';

const q = (l: string) => qsFor(MS[l], l);
const f = (l: string) => fillFor(MS[l], l);
const o = (l: string) => orderFor(MS[l], l);
const B = 'beginner', I = 'intermediate', A = 'advanced';

/** Part 1 and Part 2 of the guess papers, word for word (code put on its own lines). */
const PAPERS: WQuestion[] = [
  // ---- Part 1 ----
  q(X)(B, 'Which Xcode tool lets you run and test an iOS app on your Mac without a physical iPhone?', ['Instruments', 'iOS Simulator', 'TestFlight', 'Swift Playgrounds'], 1, 'The Simulator ships with Xcode and mimics iPhone and iPad models. Instruments profiles apps, TestFlight distributes beta builds, and Playgrounds is for quick experiments.', 'The Simulator simulates the phone.'),
  q(GIT)(B, 'What is the correct order of the basic Git workflow?', ['commit, add, push', 'push, add, commit', 'add, commit, push', 'add, push, commit'], 2, 'Stage changes with add, record them locally with commit, then upload them to GitHub with push.', 'ACP: Add, Commit, Push.'),
  q(GIT)(B, 'Which file tells Git which files to leave untracked, such as build folders?', ['.gitkeep', 'README.md', 'Info.plist', '.gitignore'], 3, '.gitignore lists patterns Git skips, for example DerivedData and .DS_Store. Info.plist is app configuration.', 'Ignore it, so .gitignore.'),
  q(CV)(B, 'let x = 5\nx = 6\n\nWhat happens?', ['Compile-time error', 'x becomes 6', 'Runtime crash', 'Only a warning'], 0, 'let creates a constant, and the compiler rejects reassignment. Use var for values that change.', 'let = locked, var = varies.'),
  q(CV)(B, 'What type does Swift infer for var price = 9.99?', ['Float', 'Decimal', 'Double', 'CGFloat'], 2, 'Floating-point literals default to Double (64-bit). Write : Float if you need Float.', 'Decimal point, Default Double.'),
  q(COL)(B, 'Which collection holds unique values with no guaranteed order?', ['Array', 'Dictionary', 'Tuple', 'Set'], 3, 'A Set stores distinct elements without order. Array is ordered and allows duplicates, and Dictionary stores key-value pairs.', 'A Set is a bag of distinct marbles.'),
  q(SC)(I, 'Which statement about struct and class is correct?', ['Structs are reference types and support inheritance', 'Classes are value types and are copied on assignment', 'Classes are reference types and support inheritance; structs are value types', 'Both are copied on assignment'], 2, 'Assigning a struct copies it, while assigning a class instance shares one object. Only classes support inheritance.', 'Struct = Snapshot (copy), Class = Connected (shared).'),
  q(OPT)(I, 'var name: String? = nil\nprint(name!)\n\nWhat does this code do?', ['Prints nil', 'Prints an empty line', 'Compile-time error', 'Runtime crash'], 3, 'The ! operator force-unwraps, and unwrapping nil crashes at runtime. Prefer if let or guard let.', 'A bang on nil goes bang.'),
  q(AC)(I, 'Which access level restricts an entity to its own source file?', ['public', 'fileprivate', 'internal', 'open'], 1, 'fileprivate allows access anywhere in the same file. internal, the default, allows access within the module.', 'file-private = file only.'),
  q(ARC)(I, 'Which reference is optional and becomes nil automatically when the object is freed?', ['weak', 'strong', 'unowned', 'lazy'], 0, 'weak references are optional and set to nil on deallocation. unowned is non-optional and crashes if used after the object is freed.', 'Weak may vanish; unowned assumes it is alive.'),
  q(FN)(I, 'func greet(person name: String) { }\n\nHow do you call it?', ['greet(name: "Ria")', 'greet("Ria")', 'greet(person name: "Ria")', 'greet(person: "Ria")'], 3, 'The first word is the argument label used by the caller, and the second is the parameter name used inside the function.', 'Outside label first, inside name second.'),
  q(CL)(I, 'Which statement about closures is true?', ['They cannot capture variables', 'They must always be named', 'They cannot be passed as arguments', 'They can capture values from their surrounding scope'], 3, 'Closures capture constants and variables from the context where they are defined, and can be stored or passed around.', 'A closure closes over its surroundings.'),
  q(HOF)(B, 'print([1, 2, 3, 4].filter { $0 % 2 == 0 })\n\nWhat is the result?', ['[1, 3]', '[2, 4]', '[false, true, false, true]', '6'], 1, 'filter keeps the elements for which the closure returns true, here the even numbers.', 'Filter keeps what passes.'),
  q(HOF)(B, 'print([1, 2, 3, 4].reduce(0, +))\n\nWhat is the value?', ['0', '4', '10', '[1, 3, 6, 10]'], 2, 'reduce combines all elements into one value, starting from the initial 0: 0+1+2+3+4.', 'Reduce turns many into one.'),
  q(PR)(I, 'How can every type that conforms to a protocol get a default method implementation?', ['Subclass the protocol', 'Write a protocol extension', 'Use a typealias', 'Mark the protocol final'], 1, 'A protocol extension can provide default implementations, which conforming types may use or override.', 'The protocol is the promise; the extension is the default gift.'),
  q(GEN)(I, 'func swapTwo<T>(_ a: inout T, _ b: inout T)\n\nWhat is T?', ['A placeholder replaced by the real type at the call', 'A class named T', 'Always Int', 'An optional'], 0, 'T is a generic type parameter. The compiler fills in the actual type, such as Int or String, when you call the function.', 'T = Type placeholder.'),
  q(ERR)(I, 'A function marked throws must be called with:', ['await', 'try, inside do-catch or another throwing function', 'async', 'defer'], 1, 'Calling a throwing function needs try. Handle the error with do-catch, or propagate it from a function that also throws.', 'Try it, then catch it.'),
  q(UI)(B, 'Which describes SwiftUI?', ['Imperative: you update each view by hand', 'Declarative: you describe the UI for a given state', 'It only works with Storyboards', 'It is written in Objective-C'], 1, 'SwiftUI describes what the UI should look like for the current state. UIKit is the imperative framework.', 'SwiftUI says what, not how.'),
  q(UI)(B, 'Which class is the core building block for a screen in UIKit?', ['View', 'UIViewController', 'NavigationStack', 'App'], 1, 'In UIKit, each screen is typically managed by a UIViewController. SwiftUI uses View structs and NavigationStack instead.', 'UIKit has controllers; SwiftUI has views.'),
  q(UI)(I, 'In SwiftUI, what happens when a @State value changes?', ['You must call reloadData', 'The app restarts', 'The view body is re-evaluated and the UI updates', 'Nothing until the next launch'], 2, 'SwiftUI tracks state and refreshes the affected views automatically, with no manual reload.', 'State changes, the UI re-draws.'),
  q(MVC)(B, 'In MVC, which layer holds data and business logic?', ['Model', 'View', 'Controller', 'Storyboard'], 0, 'The Model holds data and rules, the View displays it, and the Controller coordinates between them.', 'M = Memory of data, V = Visuals, C = Coordinator.'),
  q(MVVM)(I, "In MVVM, what is the ViewModel's role?", ['Draw the pixels on screen', 'Store app icons', 'Prepare and expose state for the view, without holding UI views', 'Replace the Model'], 2, 'The ViewModel turns Model data into display-ready state, which makes it easy to unit test.', "The ViewModel is the view's mentor, with no views inside."),
  q(VLC)(I, 'What is the order of UIViewController life-cycle calls when a screen first appears?', ['viewDidAppear, viewWillAppear, viewDidLoad', 'viewWillAppear, viewDidLoad, viewDidAppear', 'viewDidLoad, viewWillAppear, viewDidAppear', 'viewDidLoad, viewDidAppear, viewWillAppear'], 2, 'The view loads once, then is about to appear, then has appeared.', 'Load, Will, Did.'),
  q(GCD)(B, 'On which queue should UI updates run?', ['DispatchQueue.global(qos: .background)', 'Any concurrent queue', 'A custom serial queue', 'DispatchQueue.main'], 3, 'UIKit and SwiftUI must be updated on the main thread. Do heavy work on a background queue, then hop back to main.', 'UI = Main.'),
  q(ASY)(B, 'What must you write when calling an async function?', ['await', 'try!', 'defer', '@escaping'], 0, 'await marks a suspension point where the function may pause without blocking the thread.', 'await = wait without blocking.'),
  q(ACT)(I, 'What does @MainActor guarantee?', ['Code runs on a background thread', 'Code runs on the main actor, that is, the main thread', 'No data races anywhere in the app', 'The function becomes synchronous'], 1, 'Marking a type or function @MainActor makes its code run on the main actor, which is where UI work belongs.', "MainActor is the UI's actor."),
  q(NET)(I, 'let result = try await URLSession.shared.data(from: url)\n\nWhat is result?', ['Only Data', 'A String', 'A (Data, URLResponse) tuple', 'A Codable model'], 2, 'You get the bytes and the response metadata, such as the status code. Decode the Data yourself.', 'Data plus Response, a pair.'),
  q(COD)(B, 'Which protocol lets a type convert to and from JSON?', ['Hashable', 'Codable', 'Identifiable', 'Equatable'], 1, 'Codable combines Encodable and Decodable, used with JSONEncoder and JSONDecoder.', 'Co-dable: encode and decode.'),
  q(VIEW)(B, 'Which class do all visible elements in UIKit inherit from?', ['UIViewController', 'UIApplication', 'UIStoryboard', 'UIView'], 3, 'Labels, buttons and table views are all UIView subclasses. UIViewController manages a view but is not itself one.', 'Everything you See is a View.'),
  q(SB)(I, 'In Storyboards, what do IBOutlet and IBAction do?', ['IBOutlet runs code on tap; IBAction stores a view', 'IBOutlet references a UI element in code; IBAction connects a UI event to a method', 'Both create constraints', 'Both load images'], 1, 'Outlets let your code read or change a view. Actions run a method when the user taps or drags.', 'Outlet = a handle on the view; Action = what happens on tap.'),
  q(TV)(I, 'Which UITableViewDataSource method returns the number of rows in a section?', ['numberOfSections(in:)', 'tableView(_:cellForRowAt:)', 'tableView(_:numberOfRowsInSection:)', 'tableView(_:didSelectRowAt:)'], 2, 'The table asks how many rows, then asks for each cell with cellForRowAt.', 'Count first, then cells.'),
  q(AL)(B, 'What does Auto Layout use to position and size views?', ['Fixed frames only', 'Constraints', 'Gesture recognisers', 'Info.plist'], 1, 'Constraints describe relationships between views, so the layout adapts to different screen sizes and orientations.', 'Constraints are the rules for position and size.'),
  q(ST)(B, 'What is @State used for in SwiftUI?', ['Local mutable state owned by the view, which refreshes it when changed', 'Sharing data with every view in the app', 'Reading Info.plist', 'Making network calls'], 0, '@State stores simple value state that the view owns, usually marked private.', "State is the view's own memory."),
  q(ST)(I, 'What does @Binding do?', ['Creates new state', 'Stores data on disk', 'Gives a two-way connection to state owned elsewhere', 'Observes notifications'], 2, 'A child view uses @Binding to read and write a value owned by its parent, passed in with $.', 'Binding is borrowed state.'),
  q(ST)(I, 'Which macro marks a model class so SwiftUI views update when its properties change (iOS 17 and later)?', ['@Published', '@Observable', '@MainActor', '@Binding'], 1, '@Observable, from the Observation framework, tracks property access. @Published belongs to the older ObservableObject approach.', 'Observable: views observe it.'),
  q(NAV)(B, 'Which container pushes and pops screens in modern SwiftUI?', ['TabView', 'VStack', 'NavigationStack', 'Form'], 2, 'NavigationStack manages a stack of screens. TabView switches between sections, and VStack and Form only lay out content.', 'A stack of screens: push and pop.'),
  q(PL)(I, 'Which Info.plist key must be set before your app can access the camera?', ['NSCameraUsageDescription', 'CameraPermission', 'UICameraAccess', 'NSPhotoLibraryUsageDescription'], 0, 'iOS shows this text in the permission prompt. Without it the app crashes on access.', 'NS + Camera + UsageDescription: say why you need it.'),
  q(XCT)(B, 'In XCTest, test method names must begin with:', ['test', 'check', 'run', 'verify'], 0, 'XCTest discovers methods whose names start with test, such as testTotalIsCorrect.', 'No test prefix, no test run.'),
  q(XCT)(I, 'Why use a mock in a unit test?', ['To make the app look better', 'To replace a real dependency, such as the network, with a controlled stand-in', 'To speed up Xcode', 'To sign the app'], 1, 'Mocks make tests fast and repeatable, because they do not depend on a server or a database.', 'Mock = a fake to test the real thing.'),
  q(INS)(B, 'Which Instruments template shows where your app spends CPU time?', ['Leaks', 'Allocations', 'Time Profiler', 'Network'], 2, 'Time Profiler samples the call stack so you can find slow code. Leaks and Allocations deal with memory.', 'Time Profiler shows where the time goes.'),
  q(INS)(I, 'Which Instruments tool finds memory that is never released, such as from retain cycles?', ['Time Profiler', 'Leaks', 'Energy Log', 'Core Animation'], 1, 'Leaks detects objects that stay in memory with no way to reach them, a common sign of a retain cycle.', 'Leaks finds lost memory.'),

  // ---- Part 2 · Module 1 ----
  q(X)(B, 'Which IDE is used to build iOS apps?', ['Android Studio', 'Xcode', 'Eclipse', 'IntelliJ IDEA'], 1, "Xcode is Apple's IDE for iOS, iPadOS and macOS apps. Android Studio is for Android.", "X-code is Apple's code tool."),
  q(X)(B, 'Which operating system do you need to run Xcode?', ['Windows', 'Linux', 'macOS', 'Android'], 2, 'Xcode runs only on macOS, so iOS development needs a Mac.', 'Xcode needs a Mac.'),
  q(X)(I, 'Which feature can the iOS Simulator NOT provide?', ['Rotating the device', 'Different screen sizes', 'Using the physical camera', 'Simulated location'], 2, 'The Simulator can rotate, resize and fake a location, but it has no real camera. Test camera features on a real device.', 'No lens in the Simulator.'),
  q(PG)(B, 'Which task suits a Swift Playground best?', ['Trying a Swift snippet and seeing results instantly', 'Managing provisioning profiles', 'Profiling memory leaks', 'Designing storyboards'], 0, 'Playgrounds give quick feedback for learning syntax and testing small ideas without building a full app.', 'Playground = play with code.'),
  q(PG)(I, 'In an Xcode Playground, where do you see the value produced by each line?', ['The results sidebar', 'App Store Connect', 'Info.plist', 'The Git history'], 0, "The sidebar shows each line's value as you type, which makes experiments quick.", 'Results sit on the side.'),
  q(GIT)(B, 'Which command creates a new local Git repository?', ['git start', 'git init', 'git new', 'git create'], 1, 'git init turns the current folder into a Git repository.', 'init = initialise.'),
  q(GIT)(B, 'Which command copies an existing remote repository to your machine?', ['git clone', 'git copy', 'git fetch-all', 'git download'], 0, 'git clone downloads the full repository with its history and sets up the remote.', 'Clone = copy of the whole repo.'),
  q(GIT)(I, 'What does git pull do?', ['Uploads your commits', 'Deletes a branch', 'Fetches remote changes and merges them into your branch', 'Only lists branches'], 2, 'git pull is a fetch followed by a merge. git push is the one that uploads.', 'Pull = fetch + merge; push goes up.'),
  q(GIT)(I, 'Why create a branch before building a new feature?', ['To rename the project', 'To keep your changes separate from the main code until they are ready', 'To speed up the build', 'To sign the app'], 1, 'A branch isolates work, so a half-finished feature cannot break main.', 'Branch out, keep main clean.'),
  q(GIT)(A, 'Git reports a merge conflict. What should you do?', ['Delete the .git folder', 'Force push', 'Edit the conflicted files to resolve the markers, then stage and commit', 'Reinstall Xcode'], 2, 'Git marks the clashing lines. You choose the final code, remove the markers, add the file and commit.', 'Conflict: Choose, Clean, Commit.'),
  // ---- Part 2 · Module 2 ----
  q(SW)(B, 'Which company created Swift?', ['Apple', 'Google', 'Microsoft', 'Oracle'], 0, 'Apple introduced Swift in 2014 as a modern language for its platforms.', 'iOS and Swift are both from Apple.'),
  q(OPT)(B, "Which is the safest way to use an optional's value only when it exists?", ['The ! operator', 'if let', 'as!', 'try!'], 1, 'if let unwraps only when a value is present, and skips the block otherwise. ! crashes on nil.', 'If let: if there is something.'),
  q(OP)(B, 'let a = 7 / 2\n\nWhat is the value of a?', ['3.5', '3', '4', 'Compile-time error'], 1, 'Both numbers are Int, so integer division drops the fraction. Write 7.0 / 2 to get 3.5.', 'Int in, Int out.'),
  q(OPT)(I, 'let n: Int? = nil\nlet v = n ?? 10\n\nWhat is v?', ['nil', '0', 'Compile-time error', '10'], 3, 'The nil-coalescing operator ?? gives the right-hand value when the left side is nil.', '?? means: if empty, use mine.'),
  q(COL)(I, 'let scores = ["Ria": 90]\nlet r = scores["Raj"]\n\nWhat is the type of r?', ['Int', 'Int?', 'String', 'Never'], 1, 'A missing key returns nil, so a dictionary lookup always gives an optional.', 'A lookup may miss, so it is optional.'),
  q(EN)(I, 'Which enum feature lets each case carry extra data, such as case failure(String)?', ['Raw values', 'Associated values', 'Generics only', 'Extensions only'], 1, 'Associated values attach data to a case. Raw values are fixed labels for every case.', 'Associated = attached data; raw = fixed label.'),
  q(SC)(I, "A struct method that changes the struct's own properties must be marked:", ['mutating', 'static', 'final', 'override'], 0, 'Structs are value types, so a method that modifies self must say mutating, and it needs a var instance.', 'To change a struct, say mutating.'),
  q(SC)(A, 'struct P { var x = 1 }\nvar a = P()\nvar b = a\nb.x = 5\nprint(a.x)\n\nWhat prints?', ['5', '1', '0', 'Compile-time error'], 1, 'Assigning a struct makes a copy, so changing b does not affect a.', 'Struct = snapshot.'),
  q(SC)(A, 'class C { var x = 1 }\nlet a = C()\nlet b = a\nb.x = 5\nprint(a.x)\n\nWhat prints?', ['5', '1', 'Compile-time error because a is let', '0'], 0, 'a and b point to the same object. let only stops you from reassigning the reference, not from changing its properties.', 'let on a class = fixed pointer, not a frozen object.'),
  q(ARC)(A, 'Two class instances hold strong references to each other. What happens?', ['Swift frees both automatically', 'A retain cycle: neither is freed, causing a memory leak', 'Compile-time error', 'Runtime crash'], 1, 'ARC frees an object only when its strong count reaches zero. Make one side weak or unowned to break the cycle.', 'Two strong hands holding each other never let go.'),
  // ---- Part 2 · Module 3 ----
  q(FN)(B, 'func add(_ a: Int, _ b: Int) -> Int { a + b }\n\nWhich call is correct?', ['add(a: 2, b: 3)', 'add(2, 3)', 'add(_: 2, _: 3)', 'add(2: a)'], 1, 'An underscore removes the argument label, so you pass values directly.', 'Underscore = no label.'),
  q(HOF)(B, 'print([1, 2, 3].map { $0 * 10 })\n\nWhat prints?', ['[10, 20, 30]', '[1, 2, 3]', '60', '[3, 2, 1]'], 0, 'map applies the closure to every element and returns a new array of the results.', 'Map transforms each one.'),
  q(EXT)(I, 'Which can an extension NOT add to a type?', ['A computed property', 'A stored property', 'A new method', 'A new convenience initializer'], 1, "Extensions add behaviour only. Stored properties change the type's memory layout, so they are not allowed.", 'Extensions add moves, not memory.'),
  q(HOF)(I, 'print(["a", "bb", "ccc"].map { $0.count })\n\nWhat prints?', ['[1, 2, 3]', '["a", "bb"]', '6', 'Compile-time error'], 0, 'map turns each string into its length, so the result is an array of Int.', 'Map can change the type.'),
  q(HOF)(A, 'print([1, 2, 3].reduce(1) { $0 * $1 })\n\nWhat prints?', ['1', '6', '7', '123'], 1, 'It starts at 1 and multiplies: 1 x 1 x 2 x 3 = 6. $0 is the running result and $1 is the next element.', '$0 = so far, $1 = next.'),
  q(FN)(I, 'Which keyword lets a function change a passed-in value, and what must the caller write?', ['var, nothing', 'inout, and & before the argument', 'mutating, and *', 'ref, and &'], 1, 'An inout parameter is copied in and written back out. The caller marks it with &.', 'In-out needs an ampersand.'),
  q(PR)(B, 'A struct says it conforms to a protocol but does not implement a required method. What happens?', ['Runtime crash', 'Compile-time error', 'The method returns 0', 'Only a warning'], 1, 'The compiler checks protocol requirements, so a missing method fails the build.', 'A broken promise is a compile error.'),
  q(GEN)(A, 'func largest<T: Comparable>(_ a: T, _ b: T) -> T\n\nWhat does T: Comparable mean?', ['T must be a class', 'T can be any type that supports comparison operators', 'T is always Int', 'T must be optional'], 1, 'The constraint limits T to types that can be compared, so you can use > inside the function.', 'Colon = constraint: T must follow this rule.'),
  q(ERR)(I, 'What does try? produce when the function throws?', ['A crash', 'nil', 'The error', 'false'], 1, 'try? turns the result into an optional, which is nil when an error is thrown. try! would crash.', 'try? = maybe; try! = bang.'),
  q(CL)(A, 'Why write [weak self] in a closure that self stores?', ['To run the closure faster', 'To avoid a retain cycle, and self becomes optional inside', 'To make the closure escaping', 'To turn self into a struct'], 1, 'A stored closure capturing self strongly keeps self alive forever. A weak capture breaks the cycle, so you unwrap self inside.', "Weak self: don't hold on to what holds you."),
  // ---- Part 2 · Module 4 ----
  q(UI)(B, 'SwiftUI views are typically:', ['Classes', 'Structs conforming to View', 'Storyboard files', 'Objective-C protocols'], 1, 'A SwiftUI view is a lightweight struct that conforms to the View protocol.', 'SwiftUI = Structs.'),
  q(UI)(I, 'Which expression best describes SwiftUI?', ['UI = f(state)', 'UI = f(frames)', 'UI = f(storyboards)', 'UI = f(outlets)'], 0, 'In SwiftUI the UI is a result of the current state. Change the state and the UI follows.', 'State in, UI out.'),
  q(UI)(B, 'Which property must every SwiftUI View provide?', ['viewDidLoad', 'body', 'loadView', 'init(coder:)'], 1, "The body property returns the view's content. viewDidLoad belongs to UIKit.", 'Every View has a body.'),
  q(UI)(I, 'How do you change the text shown by a SwiftUI Text?', ['Call label.setNeedsDisplay', 'Change a state value that the Text uses', 'Reload the storyboard', 'Call viewDidLoad again'], 1, 'You do not touch the view directly. You update the state, and SwiftUI redraws.', 'Change the state, not the view.'),
  q(UI)(B, 'Which Xcode feature shows a live SwiftUI preview beside your code?', ['Debug Navigator', 'Canvas', 'Organizer', 'Instruments'], 1, 'The Canvas renders your #Preview so you can see changes as you type.', 'Canvas = picture of your code.'),
  q(UI)(I, 'How do you show a SwiftUI view inside a UIKit app?', ['UIHostingController', 'UIViewRepresentable', 'NSHostingView', 'SwiftUIKit'], 0, 'UIHostingController wraps a SwiftUI view so UIKit can present it.', 'Hosting: UIKit hosts SwiftUI.'),
  q(UI)(I, 'How do you use an existing UIKit view inside SwiftUI?', ['UIHostingController', 'UIViewRepresentable', 'ViewModifier', 'NavigationStack'], 1, 'UIViewRepresentable wraps a UIKit view so SwiftUI can place it in its hierarchy.', 'Representable: SwiftUI represents a UIKit view.'),
  q(UI)(I, 'After changing the array behind a UITableView in UIKit, what must you do?', ['Nothing, it updates itself', 'Call reloadData or update the affected rows', 'Restart the app', 'Recreate the window'], 1, 'UIKit is imperative. You tell the table to refresh. SwiftUI does it for you when state changes.', 'UIKit: you refresh it. SwiftUI: it refreshes itself.'),
  q(UI)(A, 'Text("Hi").padding().background(Color.red)\nText("Hi").background(Color.red).padding()\n\nWhy do these two look different?', ['Modifiers apply in order, each wrapping the previous view', 'Only the last modifier counts', 'Order never matters', 'padding is ignored after background'], 0, 'Padding first, then background colours the padded area. Background first, then padding leaves the red tight around the content with empty space outside.', 'Modifiers stack like layers, in order.'),
  q(UI)(A, 'A team must support iOS 12 devices. Which framework fits the app?', ['SwiftUI only', 'UIKit', 'Either, there is no difference', 'Neither'], 1, 'SwiftUI needs iOS 13 or later. For iOS 12 you must use UIKit.', 'SwiftUI starts at iOS 13.'),
  // ---- Part 2 · Modules 5–6 ----
  q(MVC)(B, 'In MVC, which component displays information to the user?', ['Model', 'View', 'Controller', 'Network layer'], 1, 'The View shows the UI. The Model holds data and rules, and the Controller connects the two.', 'View = what you see.'),
  q(MVVM)(B, 'What is the main benefit of MVVM over a massive view controller?', ['Easier testing and a thinner view controller', 'A smaller app size', 'Faster networking', 'No Model needed'], 0, 'Logic moves into the ViewModel, which can be unit tested without any UI.', 'MVVM = slim controller, easy tests.'),
  q(APP)(B, 'Which app state means the app is in the foreground and receiving events?', ['Inactive', 'Background', 'Suspended', 'Active'], 3, 'Active is the normal foreground state. Inactive is in the foreground but not receiving events, such as during a call.', 'Active = alive on screen.'),
  q(VLC)(I, "Where should you do one-time setup of a view controller's views?", ['viewDidAppear', 'viewWillDisappear', 'viewDidLoad', 'deinit'], 2, 'viewDidLoad runs once after the view loads. viewDidAppear runs every time the screen appears.', 'Load once, appear many times.'),
  q(GCD)(I, 'DispatchQueue.global(qos: .userInitiated).async {\n    // work\n}\n\nWhat does this do?', ['Blocks the main thread', 'Runs the block on the main thread', 'Cancels the queue', 'Runs the block asynchronously on a background thread'], 3, 'A global queue uses background threads, and async returns immediately instead of waiting.', 'Global + async = background, no waiting.'),
  q(GCD)(A, 'What happens if you call DispatchQueue.main.sync { } from the main thread?', ['It runs normally', 'Deadlock: the app freezes', 'It runs in the background', 'Compile-time error'], 1, 'sync waits for the block to finish, but the main queue is busy waiting, so neither can proceed.', 'Main waiting on main waits forever.'),
  q(TASK)(I, 'How do you start async work from ordinary synchronous code?', ['Task { }', 'async let', 'DispatchGroup', 'await'], 0, 'Task creates a new asynchronous context. await can only be used inside an async context.', 'Task starts the async story.'),
  q(TASK)(I, 'What is a task group for?', ['Running a flexible number of child tasks concurrently and collecting their results', 'Storing data safely', 'Drawing UI', 'Launching the app'], 0, 'withTaskGroup lets you add child tasks in a loop, for example one download per item, and gather results as they finish.', 'Group = many tasks, one result set.'),
  q(ACT)(I, 'What problem do actors solve?', ['UI layout', 'Slow networking', 'Data races on shared mutable state', 'Memory leaks'], 2, 'An actor lets only one task touch its state at a time, so concurrent code cannot corrupt it.', 'Actor = one at a time, no race.'),
  q(ACT)(A, "What must you write to call an actor's method from outside the actor?", ['Nothing', 'await', 'try!', 'inout'], 1, 'The call may have to wait for the actor to be free, so it is a suspension point that needs await.', "Knock with await before entering the actor's room."),
  // ---- Part 2 · Modules 7–8 ----
  q(NET)(B, 'Which Foundation class makes network requests?', ['UIView', 'URLSession', 'JSONDecoder', 'CoreData'], 1, 'URLSession sends requests and receives responses. JSONDecoder only converts data.', 'URL + Session = web conversation.'),
  q(COD)(B, 'Which type converts JSON data into Swift values?', ['JSONEncoder', 'URLComponents', 'UIImage', 'JSONDecoder'], 3, 'Decoder reads JSON into your types. Encoder goes the other way.', 'Decode = JSON in, Swift out.'),
  q(NET)(B, 'What does HTTP status 404 mean?', ['Resource not found', 'Success', 'Server error', 'Unauthorized'], 0, '404 means the server could not find the requested resource. 200 is success and 500 is a server error.', '404 = not found.'),
  q(COD)(I, 'struct User: Codable {\n    let name: String\n    let age: Int\n}\n\nThe JSON object has no age key. What happens when you decode it?', ['age becomes 0', 'age becomes nil', 'Decoding throws an error', 'The key is ignored'], 2, 'A required property with no matching key fails to decode. Make it Int? to allow a missing key.', 'Required means required; optional means maybe.'),
  q(COD)(I, 'The JSON key is user_name but your property is userName. What do you add to Codable?', ['@Published', 'typealias', 'CodingKeys', 'IBOutlet'], 2, 'A CodingKeys enum maps your property names to the JSON keys.', 'Keys map keys.'),
  q(AL)(I, 'What is the effect of ambiguous Auto Layout constraints?', ['The layout is not fully defined, so views may appear in the wrong place', 'Xcode refuses to build', 'The app crashes at launch', 'Nothing'], 0, 'Each view needs enough constraints for its position and size. Missing ones give warnings and unpredictable layouts.', 'Not enough rules, not enough layout.'),
  q(TV)(I, 'Why do you call dequeueReusableCell in a UITableView?', ['To delete cells', 'To sort rows', 'To reload data', 'To reuse off-screen cells and save memory'], 3, 'The table keeps only visible cells and recycles them as you scroll, which keeps long lists smooth.', 'Recycle cells like a conveyor belt.'),
  q(TV)(I, 'Which protocol handles row taps in a UITableView?', ['UITableViewDataSource', 'UIApplicationDelegate', 'UITableViewDelegate', 'Codable'], 2, 'The delegate responds to events such as didSelectRowAt. The data source supplies rows and cells.', 'DataSource = what to show; Delegate = what happens on tap.'),
  q(NET)(A, 'After a URLSession completion handler returns data, why update the UI with DispatchQueue.main.async?', ['URLSession always calls the completion handler on the main thread', 'The completion handler may run on a background queue, and UI must be updated on main', 'UI can be updated from any thread', 'The main queue is faster'], 1, 'Network callbacks usually arrive off the main thread. Hop to main before touching views.', 'Fetch in the background, show on main.'),
  q(NET)(A, 'Which is the correct modern way to fetch and decode a User?', ['let user = JSONDecoder().decode(User.self, from: URLSession.shared.data(from: url))', 'let data = URLSession.shared.data(from: url); JSONDecoder.decode(data)', 'let (data, _) = try await URLSession.shared.data(from: url); let user = try JSONDecoder().decode(User.self, from: data)', 'let user = URLSession.shared.data(from: url).decode(User.self)'], 2, 'The call is async and throws, so it needs try await. It returns a (Data, URLResponse) tuple, and decode also throws.', 'Try, await, take the data, then decode.'),
  // ---- Part 2 · Modules 9–10 (M9.1–M9.9; the rest of the PDF is still to come) ----
  q(SUI)(B, 'Where does a SwiftUI app start? Pick its entry point.', ['A struct marked @main that conforms to App', 'A UIViewController', 'main.swift only', 'AppDelegate only'], 0, "The App protocol defines the app's scenes, and @main marks where launch begins.", '@main + App = start here.'),
  q(LAY)(B, 'Which stack places views side by side?', ['VStack', 'ZStack', 'HStack', 'Grid'], 2, 'H is for horizontal. VStack is vertical and ZStack layers views on top of each other.', 'H = horizontal, V = vertical, Z = depth.'),
  q(ST)(A, "A child view must edit its parent's @State var isOn. What do you pass to the child's @Binding var isOn: Bool?", ['isOn', '&isOn', '$isOn', '@isOn'], 2, 'The $ prefix gives a Binding, a two-way connection to the state owned by the parent.', 'Dollar = share a two-way link.'),
  q(ST)(I, 'Why use @State instead of a plain var inside a SwiftUI view struct?', ['Plain vars are slower', '@State encrypts the value', 'Views are recreated, so @State keeps the storage outside the struct and triggers redraws', 'Plain vars are not allowed in structs'], 2, 'View structs are rebuilt often and are immutable in body. @State stores the value elsewhere and tells SwiftUI to refresh.', 'State survives the rebuild.'),
  q(LAY)(I, 'Which container lays out items in a grid and creates them lazily?', ['VStack', 'Text', 'Form', 'LazyVGrid'], 3, 'LazyVGrid arranges items in columns and builds them only as they scroll into view.', 'Lazy + V + Grid.'),
  q(NAV)(I, 'Which modifier gives a tab its icon and label in a TabView?', ['.tabItem', '.navigationTitle', '.badge', '.toolbar'], 0, 'Attach .tabItem to each child view, with a Label or Image and Text.', 'Tab + item = tabItem.'),
  q(NAV)(I, 'Which view pushes a new screen when tapped inside a NavigationStack?', ['Link', 'Button only', 'Sheet', 'NavigationLink'], 3, 'NavigationLink pushes its destination onto the stack, and the back button pops it.', 'Link to the next screen.'),
  q(ST)(A, 'A view creates and owns an @Observable model. Which wrapper should hold it?', ['@Binding', '@State', '@Published', '@EnvironmentObject'], 1, 'With the Observation framework the view that creates the model keeps it in @State, so it survives view rebuilds.', 'Own it with @State; borrow with @Binding.'),
  q(PL)(I, 'Which Info.plist key explains why the app needs your location while in use?', ['NSLocationText', 'UILocationReason', 'CLLocationDescription', 'NSLocationWhenInUseUsageDescription'], 3, 'iOS shows this text in the permission prompt. Without it the request fails.', 'NS + what + UsageDescription'),
];

